import numpy as np

def project_points(Xw, K, R, t, image_size, dist=(0.0, 0.0)):
    """Return {"uv": (N, 2), "depth": (N,), "visible": (N,) bool}."""
    Xc = Xw @ R + t
    uv = K[:2, :2] @ (Xc[:, :2] / Xc[:, 2:]).T
    return {"uv": uv.T + K[:2, 2], "depth": Xc[:, 2], "visible": Xc[:, 2] > 0}
